/* CACHE and FILES are generated by tools/package_assets.py. */
let offlineJob=null,offlineSnapshot=null,lastOfflineNotice=0;
const absoluteOfflineURL=path=>new URL(path,self.registration.scope).href;
function offlineState(state,completed=0,extra={}){
 return {type:'offline-progress',state,completed,total:FILES.length,percent:state==='ready'?100:Math.min(99,Math.floor(completed/Math.max(1,FILES.length)*100)),...extra};
}
async function publishOffline(snapshot,force=false){
 offlineSnapshot=snapshot;
 const now=Date.now();if(!force&&now-lastOfflineNotice<200)return;lastOfflineNotice=now;
 for(const client of await self.clients.matchAll({type:'window',includeUncontrolled:true}))client.postMessage(snapshot);
}
async function readOfflineStatus(){
 if(offlineSnapshot)return offlineSnapshot;
 const cache=await caches.open(CACHE);
 if(await cache.match(absoluteOfflineURL('./offline-ready.flag')))return offlineState('ready',FILES.length);
 const keys=new Set((await cache.keys()).map(request=>request.url));
 const count=FILES.filter(path=>keys.has(absoluteOfflineURL(path))).length;
 return offlineState('idle',count);
}
async function fetchOfflineFile(cache,path){
 for(let attempt=0;attempt<2;attempt++){
  const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),30000);
  try{
   const url=absoluteOfflineURL(path),response=await fetch(url,{signal:controller.signal,cache:'no-cache'});
   if(!response.ok)throw Error('HTTP '+response.status);
   await cache.put(url,response);return;
  }catch(error){if(attempt===1||error.name==='QuotaExceededError')throw error;}
  finally{clearTimeout(timer);}
 }
}
async function prepareOffline(){
 if(offlineJob)return offlineJob;
 offlineJob=(async()=>{
  let completed=0;
  try{
   const cache=await caches.open(CACHE);
   if(await cache.match(absoluteOfflineURL('./offline-ready.flag'))){await publishOffline(offlineState('ready',FILES.length),true);return;}
   const existing=new Set((await cache.keys()).map(request=>request.url));
   const missing=FILES.filter(path=>!existing.has(absoluteOfflineURL(path)));completed=FILES.length-missing.length;
   await publishOffline(offlineState('downloading',completed),true);
   let next=0;const errors=[];
   async function download(){
    while(next<missing.length&&!errors.length){
     const path=missing[next++];
     try{await fetchOfflineFile(cache,path);completed++;await publishOffline(offlineState('downloading',completed));}
     catch(error){errors.push(error);}
    }
   }
   await Promise.all(Array.from({length:Math.min(6,missing.length)},()=>download()));
   if(errors.length){await publishOffline(offlineState('error',completed,{reason:errors.some(error=>error.name==='QuotaExceededError')?'storage':'network'}),true);return;}
   await cache.put(absoluteOfflineURL('./offline-ready.flag'),new Response('ready'));
   await publishOffline(offlineState('ready',FILES.length),true);
   // Older pages still understand this completion message.
   for(const client of await self.clients.matchAll({type:'window',includeUncontrolled:true}))client.postMessage({type:'offline-ready'});
   for(const key of await caches.keys())if(key.startsWith('nightlens-')&&key!==CACHE)await caches.delete(key);
  }catch(error){await publishOffline(offlineState('error',completed,{reason:error.name==='QuotaExceededError'?'storage':'network'}),true);}
 })().finally(()=>{offlineJob=null;});
 return offlineJob;
}
self.addEventListener('install',event=>event.waitUntil(self.skipWaiting()));
self.addEventListener('activate',event=>event.waitUntil((async()=>{
 await self.clients.claim();await publishOffline(await readOfflineStatus(),true);
})()));
self.addEventListener('message',event=>{
 if(event.data?.type==='offline-prepare')event.waitUntil(prepareOffline());
 else if(event.data?.type==='offline-status')event.waitUntil((async()=>{event.source?.postMessage(await readOfflineStatus());})());
});
self.addEventListener('fetch',event=>{
 const url=new URL(event.request.url);if(url.origin!==self.location.origin||event.request.method!=='GET')return;
 event.respondWith((async()=>{
  const cache=await caches.open(CACHE),retry=url.searchParams.has('__nl_img_retry')&&/\/assets\/.+\.(png|jpe?g|webp)$/i.test(url.pathname);
  const cached=await cache.match(event.request,{ignoreSearch:retry});if(cached)return cached;
  try{return await fetch(event.request);}catch(error){
   if(event.request.mode==='navigate'){
    const current=await cache.match(absoluteOfflineURL('./index.html'));if(current)return current;
   }
   // Preserve the last complete version while a new download is incomplete.
   for(const key of await caches.keys())if(key.startsWith('nightlens-')&&key!==CACHE){const older=await caches.open(key),saved=await older.match(event.request,{ignoreSearch:retry})||(event.request.mode==='navigate'?await older.match(absoluteOfflineURL('./index.html')):undefined);if(saved)return saved;}
   throw error;
  }
 })());
});
